(4312323, 620186, 87685, '<td valign="top">nice scenery... love the place</td>', 'nice scenery... love the place', '2007-12-13 03:48:29.000000', NULL, 1),
(4312333, 621540, 34938, '<td valign="top">Fantastic rays. I think the square crop was a great choice...it lacks a little crispness, but that''s OK as it adds to what''s happening with the light. Well done</td>', 'Fantastic rays. I think the square crop was a great choice...it lacks a little crispness, but that''s OK as it adds to what''s happening with the light. Well done', '2007-12-13 04:22:46.000000', NULL, 1),
(4312335, 620308, 34938, '<td valign="top">I love taking images from my window on a plane, and this year, I have been on a few, let me tell you! Fiji, Dubai, Kenya, USA, Italy, UK, all in seperate trips, not to mention many interstate flights...but enough about me...rgis one is a beauty. Love the colours, and I love the darkness below, really makes it punch. You had a great seat at the pointy end of the plane. Love it...8</td>', 'I love taking images from my window on a plane, and this year, I have been on a few, let me tell you! Fiji, Dubai, Kenya, USA, Italy, UK, all in seperate trips, not to mention many interstate flights...but enough about me...rgis one is a beauty. Love the colours, and I love the darkness below, really makes it punch. You had a great seat at the pointy end of the plane. Love it...8', '2007-12-13 04:24:47.000000', NULL, 1),
(4312380, 621719, 34938, '<td valign="top">I really like the purple hues</td>', 'I really like the purple hues', '2007-12-13 06:50:19.000000', NULL, 1),
(4312381, 621376, 53572, '<td valign="top">interesting interpretation.  on a purely technical note, i think i would have preferred this in black and white; the colours are a little distracting from the forms.</td>', 'interesting interpretation.  on a purely technical note, i think i would have preferred this in black and white; the colours are a little distracting from the forms.', '2007-12-13 06:51:11.000000', NULL, 1),
(4312573, 620969, 86390, '<td valign="top">Great idea, that is just so sweet. Could bebenfit from alittle sharpness though. Good work</td>', 'Great idea, that is just so sweet. Could bebenfit from alittle sharpness though. Good work', '2007-12-13 09:43:17.000000', NULL, 1),
(4312577, 621501, 39679, '<td valign="top">The colors are beautiful but the shot is a tad dark.</td>', 'The colors are beautiful but the shot is a tad dark.', '2007-12-13 09:51:06.000000', NULL, 1),
(4312612, 620967, 66201, '<td valign="top">Great composition. I like the way you positioned the sun at the very far bedn of the road.</td>', 'Great composition. I like the way you positioned the sun at the very far bedn of the road.', '2007-12-13 10:25:11.000000', NULL, 1),
(4312620, 621327, 66201, '<td valign="top">A really strange and captivating image. I like the light rings in the sky. The front left of the church building is somewhat blown out, but in general this is an intriguing image.</td>', 'A really strange and captivating image. I like the light rings in the sky. The front left of the church building is somewhat blown out, but in general this is an intriguing image.', '2007-12-13 10:26:53.000000', NULL, 1),
(4312624, 621313, 66201, '<td valign="top">A beautifully shot image, with great light control. It''s a stretch for me in terms of the challenge topic, but it''s a great image nevertheless.</td>', 'A beautifully shot image, with great light control. It''s a stretch for me in terms of the challenge topic, but it''s a great image nevertheless.', '2007-12-13 10:27:54.000000', NULL, 1),
(4312627, 621678, 36888, '<td valign="top">other than the border  I really like the photo 8</td>', 'other than the border  I really like the photo 8', '2007-12-13 10:29:47.000000', NULL, 1),
(4312628, 621733, 66201, '<td valign="top">Lovely capture. I find the foreground darkness too dominating. If the wooden railings had been more of a discrete frame, it might have given the image more balance. As it stands, it becomes an effort to find your subject - as opposed to drawing the viewer in (not sure if that makes any sense). Love the warm tones and low light.</td>', 'Lovely capture. I find the foreground darkness too dominating. If the wooden railings had been more of a discrete frame, it might have given the image more balance. As it stands, it becomes an effort to find your subject - as opposed to drawing the viewer in (not sure if that makes any sense). Love the warm tones and low light.', '2007-12-13 10:29:51.000000', NULL, 1),
(4312634, 621369, 36888, '<td valign="top">This isn''t a "Fantasy Challenge". HaHa  I love the Cubs fans, dedicated to the end.  6</td>', 'This isn''t a "Fantasy Challenge". HaHa  I love the Cubs fans, dedicated to the end.  6', '2007-12-13 10:33:08.000000', NULL, 1),
(4312638, 621708, 66201, '<td valign="top">I appreciate the talent in this picture: great composition, excellent light and conversion. But it really doesn''t speak "heaven" to me. Yes I get the title, but the aggression and the attitude just communicate anger and violence: well this was my first reaction on seeing the image. I then read the title and went "oh okay I see what you''re saying", but it''s first impressions that count. I would probably have scored this higher over on the "Hell" challenge side.</td>', 'I appreciate the talent in this picture: great composition, excellent light and conversion. But it really doesn''t speak "heaven" to me. Yes I get the title, but the aggression and the attitude just communicate anger and violence: well this was my first reaction on seeing the image. I then read the title and went "oh okay I see what you''re saying", but it''s first impressions that count. I would probably have scored this higher over on the "Hell" challenge side.', '2007-12-13 10:33:37.000000', NULL, 1),
(4312644, 621090, 36888, '<td valign="top">wheres the thumb:~ sorry-I couldn''t resist . 6</td>', 'wheres the thumb:~ sorry-I couldn''t resist . 6', '2007-12-13 10:36:41.000000', NULL, 1),
