INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4312894, 620186, 58785, '<td valign="top">Nice. I wish there would be a little different cloud formation, it could make this photo a killer.</td>', 'Nice. I wish there would be a little different cloud formation, it could make this photo a killer.', '2007-12-13 13:04:44.000000', NULL, 1),
(4312897, 621016, 58785, '<td valign="top">Nothing like being creative and taking risks for what you love most... Photography in this case, and I really like this shot. Good job :)</td>', 'Nothing like being creative and taking risks for what you love most... Photography in this case, and I really like this shot. Good job :)', '2007-12-13 13:05:34.000000', NULL, 1),
(4312898, 621484, 58785, '<td valign="top">Very affective photo. It does look like heaven on earth :)</td>', 'Very affective photo. It does look like heaven on earth :)', '2007-12-13 13:06:04.000000', NULL, 1),
(4312903, 621377, 58785, '<td valign="top">nice. Very nice job on the hair, and composition. if you didn''t have strings showing, I would give you 9, now only 8.5 :)</td>', 'nice. Very nice job on the hair, and composition. if you didn''t have strings showing, I would give you 9, now only 8.5 :)', '2007-12-13 13:07:13.000000', NULL, 1),
(4312905, 620920, 58785, '<td valign="top">Well, I think we could say "gone to heaven" hopefully. Kind of dark for begin positive here. I like it as a photo, nice composition :)</td>', 'Well, I think we could say "gone to heaven" hopefully. Kind of dark for begin positive here. I like it as a photo, nice composition :)', '2007-12-13 13:08:19.000000', NULL, 1),
(4312909, 621650, 58785, '<td valign="top">Nice, creative shot. I like the borders, and bright light. Although, i am not sure about the color green for &amp;#8220;heaven&amp;#8221; concept. Still is a very nice photo :)</td>', 'Nice, creative shot. I like the borders, and bright light. Although, i am not sure about the color green for &#8220;heaven&#8221; concept. Still is a very nice photo :)', '2007-12-13 13:09:25.000000', NULL, 1),
(4312911, 620746, 58785, '<td valign="top">Well, I think what you are saying here is "Above there is heaven"? I am not sure, unless if "wires" spelled different in your country LOL... Sorry, I didn''t want robe rude, just a joke :)</td>', 'Well, I think what you are saying here is "Above there is heaven"? I am not sure, unless if "wires" spelled different in your country LOL... Sorry, I didn''t want robe rude, just a joke :)', '2007-12-13 13:10:46.000000', NULL, 1),
(4312913, 619984, 58785, '<td valign="top">True... very true. I like the photo, good composition :)</td>', 'True... very true. I like the photo, good composition :)', '2007-12-13 13:11:25.000000', NULL, 1),
(4312915, 621275, 58785, '<td valign="top">True... Although, I think they should be the angels of the heaven. No arguments there though, that''s what you feel, it''s ok. Nice photo for a family album :)</td>', 'True... Although, I think they should be the angels of the heaven. No arguments there though, that''s what you feel, it''s ok. Nice photo for a family album :)', '2007-12-13 13:12:57.000000', NULL, 1),
(4312919, 620905, 58785, '<td valign="top">Nice try. Rocks though kind of distracting. I am going to think on my way out to bright light "Would I be tripping on one of those, I better be careful." :P</td>', 'Nice try. Rocks though kind of distracting. I am going to think on my way out to bright light "Would I be tripping on one of those, I better be careful." :P', '2007-12-13 13:14:37.000000', NULL, 1),
(4312925, 621731, 58785, '<td valign="top">If this lady would be on a white ground... Well, too much wish I guess. I like the photo, very nice :)</td>', 'If this lady would be on a white ground... Well, too much wish I guess. I like the photo, very nice :)', '2007-12-13 13:17:15.000000', NULL, 1),
(4312947, 621600, 64446, '<td valign="top">Interesting geometrice abstract with those lines and shapes.</td>', 'Interesting geometrice abstract with those lines and shapes.', '2007-12-13 13:42:01.000000', NULL, 1),
(4312951, 621719, 66201, '<td valign="top">Lovely composition - almost looks as if there is an invisible line between the tree and the moon/sun.</td>', 'Lovely composition - almost looks as if there is an invisible line between the tree and the moon/sun.', '2007-12-13 13:44:05.000000', NULL, 1),
(4312954, 621399, 66201, '<td valign="top">The loveliest of the "heavenly skies" images. Love the golden hues and the crispness of the rays below the clouds. The tiny details on the horizon are also so sharp, but are just enough to give a sense of scale.</td>', 'The loveliest of the "heavenly skies" images. Love the golden hues and the crispness of the rays below the clouds. The tiny details on the horizon are also so sharp, but are just enough to give a sense of scale.', '2007-12-13 13:45:48.000000', NULL, 1),
(4312955, 621612, 66201, '<td valign="top">A super modernist image: abstract and really striking.</td>', 'A super modernist image: abstract and really striking.', '2007-12-13 13:46:40.000000', NULL, 1),
(4312956, 621138, 66201, '<td valign="top">Nicely done: perfect lighting.</td>', 'Nicely done: perfect lighting.', '2007-12-13 13:46:49.000000', NULL, 1),
(4312960, 621734, 58785, '<td valign="top">I say this is a nice pose. Nice composition. Now, it''s dark because angel is sleeping? I wish there would be a little bit defuse glow around her somehow. Also, the lines in the background is a bit distracting :/ Not bad photo overall though :)</td>', 'I say this is a nice pose. Nice composition. Now, it''s dark because angel is sleeping? I wish there would be a little bit defuse glow around her somehow. Also, the lines in the background is a bit distracting :/ Not bad photo overall though :)', '2007-12-13 13:50:43.000000', NULL, 1),
(4312973, 620351, 58785, '<td valign="top">You know, this is like a line between heaven and hell. The red line in horizon looks like a crack to hell, but then again up and down of the line sure seems like heavens :) nice capture :)</td>', 'You know, this is like a line between heaven and hell. The red line in horizon looks like a crack to hell, but then again up and down of the line sure seems like heavens :) nice capture :)', '2007-12-13 13:58:07.000000', NULL, 1),
(4312975, 619979, 58785, '<td valign="top">A modern heaven where you take planes :P If you crop the photo a it to the clouds, and give a bit more contrast, it would be better in my opinion :)</td>', 'A modern heaven where you take planes :P If you crop the photo a it to the clouds, and give a bit more contrast, it would be better in my opinion :)', '2007-12-13 13:59:32.000000', NULL, 1),
(4312983, 621614, 58785, '<td valign="top">Focus on the branches at left, not much going on. Quality low... I think the idea is not bad but execution is terrible, and I don''t use that word often :( (Don''t tell this comment to your kids please, let''s have them think that''s a real heaven''s day anyway :)</td>', 'Focus on the branches at left, not much going on. Quality low... I think the idea is not bad but execution is terrible, and I don''t use that word often :( (Don''t tell this comment to your kids please, let''s have them think that''s a real heaven''s day anyway :)', '2007-12-13 14:02:35.000000', NULL, 1),
