(4316845, 621204, 51793, '<td valign="top">oh no it looks liek they both moved... JMO I think this shot would have been much better without the people standing in it. It''s very pretty and the leading lines are great. maybe use it for a free study without the people. 8 from me. would have bee a 10 without them.</td>', 'oh no it looks liek they both moved... JMO I think this shot would have been much better without the people standing in it. It''s very pretty and the leading lines are great. maybe use it for a free study without the people. 8 from me. would have bee a 10 without them.', '2007-12-16 09:39:50.000000', NULL, 1),
(4316846, 620351, 51793, '<td valign="top">Very pretty shot.</td>', 'Very pretty shot.', '2007-12-16 09:40:31.000000', NULL, 1),
(4316891, 620947, 67152, '<td valign="top">i really like the intersecting lines on the sailboat - i am not a fan the large amount of black area created by the hull of the ship - it seems like lost space and the crop at the top so we see just the tip of one of the cross mast beams seems a bit forced.</td>', 'i really like the intersecting lines on the sailboat - i am not a fan the large amount of black area created by the hull of the ship - it seems like lost space and the crop at the top so we see just the tip of one of the cross mast beams seems a bit forced.', '2007-12-16 10:24:45.000000', NULL, 1),
(4316894, 621376, 67152, '<td valign="top">very dramatic image - you will likely get a great deal of harsh opinions for your choice of theme - but I will not be in that group - I think it is an excellent shot and fits the theme very well.</td>', 'very dramatic image - you will likely get a great deal of harsh opinions for your choice of theme - but I will not be in that group - I think it is an excellent shot and fits the theme very well.', '2007-12-16 10:26:03.000000', NULL, 1),
(4316895, 621732, 67152, '<td valign="top">good concept and set up - but the super shallow DOF makes the back of the cake a bit unappetising to me for some reason</td>', 'good concept and set up - but the super shallow DOF makes the back of the cake a bit unappetising to me for some reason', '2007-12-16 10:26:38.000000', NULL, 1),
(4316897, 620907, 67152, '<td valign="top">good effort but the centered horizon, the lack of dramatic lighting and color and the lack of foreground object to draw me prevent me from scoring this very highly</td>', 'good effort but the centered horizon, the lack of dramatic lighting and color and the lack of foreground object to draw me prevent me from scoring this very highly', '2007-12-16 10:28:13.000000', NULL, 1),
(4316898, 620967, 67152, '<td valign="top">wonderful composition - the road leading to the sun works very well.  I just wish the horizon was not almost dead center - i think a lower angle to show more of the road or a higher angle to show more of the sky would have worked out really nicely</td>', 'wonderful composition - the road leading to the sun works very well.  I just wish the horizon was not almost dead center - i think a lower angle to show more of the road or a higher angle to show more of the sky would have worked out really nicely', '2007-12-16 10:29:10.000000', NULL, 1),
(4316903, 620926, 67152, '<td valign="top">nice capture of the bird in flight - too bad the tip of the wing is clipped off</td>', 'nice capture of the bird in flight - too bad the tip of the wing is clipped off', '2007-12-16 10:31:46.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4316905, 619984, 67152, '<td valign="top">really nice theme for this challenge - the only thing that bothers me is the noise in the image</td>', 'really nice theme for this challenge - the only thing that bothers me is the noise in the image', '2007-12-16 10:32:20.000000', NULL, 1),
(4316906, 621390, 67152, '<td valign="top">beautiful scenery - love the recurring layers of the rocks</td>', 'beautiful scenery - love the recurring layers of the rocks', '2007-12-16 10:33:06.000000', NULL, 1),
(4316907, 620924, 67152, '<td valign="top">pretty scene - the tips of the ski poles actually provide an unnecessary distraction to the shot.  more of the ski poles or a skier in the frame would have worked better here</td>', 'pretty scene - the tips of the ski poles actually provide an unnecessary distraction to the shot.  more of the ski poles or a skier in the frame would have worked better here', '2007-12-16 10:34:07.000000', NULL, 1),
(4316912, 621050, 67152, '<td valign="top">i like the layers of blue that you have captured - i just don''t see a specific item to draw me into the photo.  The sky seems a bit noisy and the overall image is a bit blurry or out of focus.</td>', 'i like the layers of blue that you have captured - i just don''t see a specific item to draw me into the photo.  The sky seems a bit noisy and the overall image is a bit blurry or out of focus.', '2007-12-16 10:35:42.000000', NULL, 1),
(4316915, 620295, 67152, '<td valign="top">Really nice capture of the house, the trees in the background and the pool in front.  I just am not sold on the out of focus flowers in the foreground.  They seem to add more distraction to the photo.  If you selected a much smaller apeture, you could have potentially got all in focus and this would come off a bit better.  The other option would have been to get closer to the flowers and make them more pronounced and use the OOF flowers to frame the shot in a nice way.</td>', 'Really nice capture of the house, the trees in the background and the pool in front.  I just am not sold on the out of focus flowers in the foreground.  They seem to add more distraction to the photo.  If you selected a much smaller apeture, you could have potentially got all in focus and this would come off a bit better.  The other option would have been to get closer to the flowers and make them more pronounced and use the OOF flowers to frame the shot in a nice way.', '2007-12-16 10:38:00.000000', NULL, 1),
(4316916, 621032, 67152, '<td valign="top">clearly fits the challenge in my book.  But, to be honest, the shot does not hold a great deal of interest.  There is too much of the plain blue sky and the light over the roof would likely have come off a lot better if it were behind the cross - emphasizing the theme you were going after.</td>', 'clearly fits the challenge in my book.  But, to be honest, the shot does not hold a great deal of interest.  There is too much of the plain blue sky and the light over the roof would likely have come off a lot better if it were behind the cross - emphasizing the theme you were going after.', '2007-12-16 10:39:31.000000', NULL, 1),
(4316919, 621327, 67152, '<td valign="top">Very creative take .  THe distortion of the chuch is a very strange effect, but that is one cool ring that the ''traveler'' is looking at</td>', 'Very creative take .  THe distortion of the chuch is a very strange effect, but that is one cool ring that the ''traveler'' is looking at', '2007-12-16 10:40:35.000000', NULL, 1),
(4316921, 619981, 67152, '<td valign="top">nice layers of colors and textures created by the sand, the sea, and the sky.  i wish there were a specific subject to draw me into the shot - i think this setting has a lot of potential.  But I must confess that the title seems a bit forced and confusing</td>', 'nice layers of colors and textures created by the sand, the sea, and the sky.  i wish there were a specific subject to draw me into the shot - i think this setting has a lot of potential.  But I must confess that the title seems a bit forced and confusing', '2007-12-16 10:42:43.000000', NULL, 1),
(4316925, 621678, 67152, '<td valign="top">beautiful scene with the snow and the church - the edging around the photo really works to show the snow - i like!</td>', 'beautiful scene with the snow and the church - the edging around the photo really works to show the snow - i like!', '2007-12-16 10:43:47.000000', NULL, 1),
(4316927, 620969, 68599, '<td valign="top">Adorable baby, but it''s OOF</td>', 'Adorable baby, but it''s OOF', '2007-12-16 10:43:51.000000', NULL, 1),
