(4317166, 621399, 52549, '<td valign="top">Definitely my favourite so far. Great shot. Hope for top 3 for you.</td>', 'Definitely my favourite so far. Great shot. Hope for top 3 for you.', '2007-12-16 13:38:39.000000', NULL, 1),
(4317235, 621134, 85510, '<td valign="top">This is gorgeous and perfect according to me! Great job!</td>', 'This is gorgeous and perfect according to me! Great job!', '2007-12-16 15:16:45.000000', NULL, 1),
(4317240, 621275, 85510, '<td valign="top">That is a wonderful thought and I''m glad that you do, but I think that this doesn''t portray "heaven" in a general enough sense for this challenge''s purpose.</td>', 'That is a wonderful thought and I''m glad that you do, but I think that this doesn''t portray "heaven" in a general enough sense for this challenge''s purpose.', '2007-12-16 15:21:14.000000', NULL, 1),
