(4317245, 621649, 85510, '<td valign="top">This is a brilliant idea and has wonderful composition!</td>', 'This is a brilliant idea and has wonderful composition!', '2007-12-16 15:25:16.000000', NULL, 1),
(4317247, 620707, 85510, '<td valign="top">Great idea!</td>', 'Great idea!', '2007-12-16 15:26:11.000000', NULL, 1),
