(4317261, 621016, 85510, '<td valign="top">Haha!</td>', 'Haha!', '2007-12-16 15:34:53.000000', NULL, 1),
(4317310, 621399, 3746, '<td valign="top">Hi, you have probably heard this a hundred times already, but I reckon this will ribbon.. nice shot. I''m hoping my "hell" shot will be up there on the frontpage with you!<br/> <br/>Would love to know who shot this.. bumping up to a 9</td>', 'Hi, you have probably heard this a hundred times already, but I reckon this will ribbon.. nice shot. I''m hoping my "hell" shot will be up there on the frontpage with you! Would love to know who shot this.. bumping up to a 9', '2007-12-16 16:26:18.000000', NULL, 1),
(4317312, 621376, 3746, '<td valign="top">strong, powerful, evocative.. it might get caned by a lot of voters, but its a great statement.</td>', 'strong, powerful, evocative.. it might get caned by a lot of voters, but its a great statement.', '2007-12-16 16:26:56.000000', NULL, 1),
(4317315, 621016, 3746, '<td valign="top">This really stands out in the thumbnails.. a lighthearted look at the challenge. not really encompassing the heaven challenge in its entirety, but its a good shot. the expression on the models face is priceless..</td>', 'This really stands out in the thumbnails.. a lighthearted look at the challenge. not really encompassing the heaven challenge in its entirety, but its a good shot. the expression on the models face is priceless..', '2007-12-16 16:27:48.000000', NULL, 1),
(4317317, 621484, 3746, '<td valign="top">Wonderful mist, I can see where you are going by trying to exemplify what the general perceived vision of heaven is by all those religious types.. so I am making the connection there.. its a hard challenge to nail, you made a good effort. 7</td>', 'Wonderful mist, I can see where you are going by trying to exemplify what the general perceived vision of heaven is by all those religious types.. so I am making the connection there.. its a hard challenge to nail, you made a good effort. 7', '2007-12-16 16:30:00.000000', NULL, 1),
(4317318, 620226, 3746, '<td valign="top">Hard challenge to nail this one.. but you have tried to tie together the whole paradise/heaven thing here.  Lovely shot, would of liked to of seen this in a postcard format.. good effort. 7</td>', 'Hard challenge to nail this one.. but you have tried to tie together the whole paradise/heaven thing here.  Lovely shot, would of liked to of seen this in a postcard format.. good effort. 7', '2007-12-16 16:30:49.000000', NULL, 1),
(4317321, 621428, 3746, '<td valign="top">OK, if people don''t know Zeppelin then they will probably mark this down as a result.  Sadly on DPC you have to shove the obvious into voters faces but I feel calling this "Stairway to heaven" would of cheapened the shot..I hope this does well..<br/> <br/>THe high contrast BW conversion is great and compliments this shot admirably. upping to an 8</td>', 'OK, if people don''t know Zeppelin then they will probably mark this down as a result.  Sadly on DPC you have to shove the obvious into voters faces but I feel calling this "Stairway to heaven" would of cheapened the shot..I hope this does well.. THe high contrast BW conversion is great and compliments this shot admirably. upping to an 8', '2007-12-16 16:33:32.000000', NULL, 1),
(4317348, 621540, 70661, '<td valign="top">Very nice take on the challenge.</td>', 'Very nice take on the challenge.', '2007-12-16 17:02:53.000000', NULL, 1),
