(4317410, 621016, 40355, '<td valign="top">This is the best in the challenge, I hope it gets the blue!  His expression is priceless.</td>', 'This is the best in the challenge, I hope it gets the blue!  His expression is priceless.', '2007-12-16 18:12:15.000000', NULL, 1),
(4317412, 621211, 85437, '<td valign="top">VERY pretty.  Love the B&amp;W look for this.</td>', 'VERY pretty.  Love the B&W look for this.', '2007-12-16 18:15:14.000000', NULL, 1),
(4317417, 620994, 40355, '<td valign="top">This may have had real potential, but suffers from two flaws: we''re looking at the back quarters of their heads, and nearly half the photo is inky black and contains nothing.</td>', 'This may have had real potential, but suffers from two flaws: we''re looking at the back quarters of their heads, and nearly half the photo is inky black and contains nothing.', '2007-12-16 18:19:09.000000', NULL, 1),
(4317419, 621204, 40355, '<td valign="top">The scene and background are really well composed and exposed, but the movement evident in the models makes them soft in an otherwise tack-sharp image, which takes away from it.</td>', 'The scene and background are really well composed and exposed, but the movement evident in the models makes them soft in an otherwise tack-sharp image, which takes away from it.', '2007-12-16 18:21:37.000000', NULL, 1),
(4317421, 620947, 40355, '<td valign="top">Reducing the amout of black nothingness at the bottom of the frame would have strengthened the image.</td>', 'Reducing the amout of black nothingness at the bottom of the frame would have strengthened the image.', '2007-12-16 18:22:39.000000', NULL, 1),
(4317422, 621398, 40355, '<td valign="top">Crooked horizon; takes away from an otherwise lovel shot.</td>', 'Crooked horizon; takes away from an otherwise lovel shot.', '2007-12-16 18:23:22.000000', NULL, 1),
(4317424, 621014, 65234, '<td valign="top">Doesn''t look terribly appealing, but then I am not a bee.  Not sure if maybe it would look better with more color or contrast?</td>', 'Doesn''t look terribly appealing, but then I am not a bee.  Not sure if maybe it would look better with more color or contrast?', '2007-12-16 18:27:45.000000', NULL, 1),
