(4317432, 621732, 65234, '<td valign="top">Mmm, looks like chocolate cheesecake.  Definitely heavenly.  I like the color palette ... that first bite in focus looks seriously appetizing!</td>', 'Mmm, looks like chocolate cheesecake.  Definitely heavenly.  I like the color palette ... that first bite in focus looks seriously appetizing!', '2007-12-16 18:31:58.000000', NULL, 1),
(4317433, 621558, 65234, '<td valign="top">Pretty scene; wish there wasn''t a streak of something dark in the middle of the golden gleam.</td>', 'Pretty scene; wish there wasn''t a streak of something dark in the middle of the golden gleam.', '2007-12-16 18:32:47.000000', NULL, 1),
