(4317443, 621211, 65234, '<td valign="top">Lovely idea and it does convey a sense of freedom and innocence.</td>', 'Lovely idea and it does convey a sense of freedom and innocence.', '2007-12-16 18:47:59.000000', NULL, 1),
(4317445, 620186, 65234, '<td valign="top">My favorite of the heavenly landscapes.</td>', 'My favorite of the heavenly landscapes.', '2007-12-16 18:48:23.000000', NULL, 1),
(4317446, 621327, 65234, '<td valign="top">Nice effect and interesting interpretation.</td>', 'Nice effect and interesting interpretation.', '2007-12-16 18:48:49.000000', NULL, 1),
(4317448, 621399, 65234, '<td valign="top">Lovely golden rays.  Looks peaceful.</td>', 'Lovely golden rays.  Looks peaceful.', '2007-12-16 18:48:53.000000', NULL, 1),
