INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4322926, 620914, 24454, '<td valign="top">Ahhhhhh. . ..ya gotta love those non-artistic voters!   I totally love this, and think the blur is perfect.   I have been so tempted at times to submit photos using blur to make them awesome (for my tastes anyway). . .but in the end. . .I resisted realizing they just haven''t caught on to the new beautiful artistic trend!   And I''m sorry for that. . .because I think this is beautiful!<br/> <br/></td>', 'Ahhhhhh. . ..ya gotta love those non-artistic voters!   I totally love this, and think the blur is perfect.   I have been so tempted at times to submit photos using blur to make them awesome (for my tastes anyway). . .but in the end. . .I resisted realizing they just haven''t caught on to the new beautiful artistic trend!   And I''m sorry for that. . .because I think this is beautiful! ', '2007-12-19 10:56:20.000000', NULL, 0),
